// Extract event info, validate the HMAC SHA-256 signature (fail-closed), and parse the task key.
//
// The signature is checked over the exact bytes the forge sent. Behind a Webhook v2
// with `rawBody: true`, n8n 2.12.3 delivers them in the `data` binary property and
// never as `$json.rawBody` (#1712, lesson-467); `getBinaryDataBuffer` reads them in
// either binary storage mode. No bytes means nothing to verify, so nothing is
// trusted: re-serialising the parsed body is deliberately not a fallback, because
// it never reproduces what a forge signed, and it would verify bytes nobody sent.
const crypto = require('crypto');
let raw = null;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  raw = null;
}
const body = (typeof $json.body === 'object' && $json.body !== null) ? $json.body : {};

const headers = $json.headers || {};
const action = body.action || 'push';
const pr = body.pull_request || {};
const issue = body.issue || {};
const repo = body.repository || {};
const isMerged = Boolean(pr.merged);

// An `issues` event carries `issue` and no `pull_request`. Gitea also sends an
// `issue` object for pull-request comment events, where `issue.pull_request` is
// populated -- excluded here, or a PR comment would be treated as a new issue.
const isIssueEvent = Boolean(body.issue && !body.pull_request && !issue.pull_request);

const title = pr.title || issue.title || body.head_commit?.message || '';
const branch = pr.head?.ref || body.ref || '';
const prUrl = pr.html_url || '';
const issueUrl = issue.html_url || '';
const issueNumber = issue.number || body.number || null;
const repoOwner = repo.owner?.login || repo.owner?.username || (repo.full_name || '').split('/')[0] || '';
const repoName = repo.name || '';

// Match task key pattern (e.g. IDP-035, GITOPS-003, APP-CONFIG-008).
//
// The AREA may itself be hyphenated -- `APP-CONFIG`, `CI-GATE`, `SEC-VIKUNJA`
// are live on this board. A single `[A-Z]{2,10}-(\d+)` truncates those to
// `CONFIG-008` / `GATE-018` / `VIKUNJA-001`, because `\b` lets the match restart
// after the first hyphen. Measured 2026-09-05 over 300 real issue titles: 25 of
// the 256 that matched were truncated, spanning five whole AREAs.
//
// The truncation could not surface as a failed lookup, which is why it survived:
// `?s=` is a SUBSTRING search, so `?s=CONFIG-008` still finds a task titled
// `APP-CONFIG-008: ...`. It surfaces only as a collision between two AREAs
// sharing a final segment -- and by then two tickets share one key.
//
// Repeating the segment keeps the whole AREA. Verified over the same 300 titles:
// the set of titles that match is IDENTICAL (256), so no event starts or stops
// being processed; 25 of them merely carry their full key now.
const match = (title + ' ' + branch).toUpperCase().match(/\b([A-Z]{2,10}(?:-[A-Z]{2,10})*)-(\d+)\b/);
const taskKey = match ? match[0] : null;
const taskId = match ? parseInt(match[2], 10) : null;

// HMAC validation: strictly fail-closed. Gitea sends bare hex, GitHub `sha256=<hex>`.
const isGitHub = Boolean(headers['x-hub-signature-256']);
const isGitea = Boolean(headers['x-gitea-signature']);
const sig = String(headers['x-hub-signature-256'] || headers['x-gitea-signature'] || '').replace(/^sha256=/, '');
const secret = (isGitHub && $env.GITHUB_WEBHOOK_SECRET) || (isGitea && $env.GITEA_WEBHOOK_SECRET) || $env.FORGE_WEBHOOK_SECRET || '';
let isValidSig = false;

if (secret && sig && raw && raw.length > 0) {
  const expected = crypto.createHmac('sha256', secret).update(raw).digest();
  // Invalid hex decodes short, so the length check rejects it before the compare.
  const given = Buffer.from(sig, 'hex');
  isValidSig = given.length === expected.length && crypto.timingSafeEqual(given, expected);
}

let targetBucket = 'In Progress';
let isDone = false;
if (action === 'closed' && isMerged) {
  targetBucket = 'Done';
  isDone = true;
} else if (['opened', 'synchronize', 'reopened'].includes(action)) {
  targetBucket = 'In Review';
  isDone = false;
}

// The create-path's trigger floor. It mirrors `add-to-project.yml`, the workflow
// being retired, which fires on `opened` and `reopened` and nothing else -- so
// the invariant ported here is exactly the one that existed, not a wider one.
// `closed` and `edited` deliberately fall through to a 200 without creating:
// creating a task from a closing issue would resurrect work, not track it.
const CREATE_ACTIONS = ['opened', 'reopened'];
const isCreateCandidate = Boolean(taskKey && isValidSig && isIssueEvent && CREATE_ACTIONS.includes(action));

// What a pull-request event may write, forward only (ADR-066 D4; the operator's
// rule of 2026-09-27, APP-CONFIG-016). Opening or reopening a PR links it with
// one comment. A merge marks the task done. Nothing else writes: a push, a
// review or PR comment, a sync, an edit or an unmerged close would each have
// added a comment and set `done: false`, un-doing finished work. A comment
// event carries `pull_request` too on GitHub, so it is excluded by `comment`.
const isPullRequestEvent = Boolean(body.pull_request) && !body.comment && !body.review;
let prWriteKind = 'none';
if (isPullRequestEvent && ['opened', 'reopened'].includes(action)) {
  prWriteKind = 'comment';
} else if (isPullRequestEvent && action === 'closed' && isMerged) {
  prWriteKind = 'done';
}
const isTrackedPrEvent = Boolean(taskKey && isValidSig && prWriteKind !== 'none');

return [{
  json: {
    taskKey: taskKey,
    taskId: taskId,
    action: action,
    isMerged: isMerged,
    isDone: isDone,
    targetBucket: targetBucket,
    prUrl: prUrl,
    title: title,
    issueUrl: issueUrl,
    issueNumber: issueNumber,
    repoOwner: repoOwner,
    repoName: repoName,
    isIssueEvent: isIssueEvent,
    isCreateCandidate: isCreateCandidate,
    prWriteKind: prWriteKind,
    isTrackedPrEvent: isTrackedPrEvent,
    hasTask: Boolean(taskKey && isValidSig),
    isValidSig: isValidSig
  }
}];

// Find the task this pull request names -- by an EXACT key match -- and build
// what the writes after it send.
//
// READ THE ITEMS, NOT `$json`. An HTTP node handed a JSON array emits ONE ITEM
// PER ELEMENT, so `$json` here is the first task, not the list. This node read
// `$json` as the list until APP-CONFIG-016 (#1871): with a match it saw one
// object and concluded "no results", and with no match the search emitted no
// item at all, so no pull request ever reached its task. `$input.all()` covers
// every shape: split items, one item wrapping an array or `{data: [...]}`, and
// the empty item `alwaysOutputData` emits.
const event = $('Parse Forge Event').first().json;
const items = $input.all().map(i => i.json);

// A failed search is not an empty one. The search node has no `onError`, so a
// 401 or a timeout halts the run before this node; an error item reaching here
// means someone added one, and answering "no task" for it would be a lie.
const failed = items.find(i => i && i.error);
if (failed) {
  throw new Error('Vikunja task search failed: ' + JSON.stringify(failed.error).slice(0, 200));
}

let results;
if (items.length === 1 && Array.isArray(items[0])) {
  results = items[0];
} else if (items.length === 1 && items[0] && Array.isArray(items[0].data)) {
  results = items[0].data;
} else {
  results = items.filter(i => i && i.id);
}

// `?s=` is a SUBSTRING search, so `TOOL-035` also finds `TOOL-0350: ...`, and
// taking `results[0]` would mark the wrong task done (#1692). The rule is
// `Extract Issue Task Match`'s: the title starts with the key, and the next
// character is not a digit.
const key = (event.taskKey || '').toUpperCase();
const task = results.find(t => {
  const title = (t.title || '').toUpperCase();
  return key && title.startsWith(key) && !/[0-9]/.test(title.charAt(key.length));
}) || null;

// Vikunja 1.0's `POST /tasks/{id}` is a FULL update: `Task.updateSingleTask`
// clears description, priority, dates and colour when the body omits them, and
// rejects an empty title. So the write sends the task as searched, with only
// `done` changed. The field-scoped `POST /tasks/bulk` would need a token
// permission (`tasks.update_bulk`) neither environment's token carries.
const merged = event.prWriteKind === 'done';
return [{
  json: {
    ...event,
    taskId: task ? task.id : null,
    hasMatchedTask: Boolean(task),
    updateBody: task ? Object.assign({}, task, { done: true }) : null,
    comment: 'Linked PR: ' + event.prUrl + ' (' + (merged ? 'merged' : event.action) + ')',
  }
}];

// Decide whether the issue's task already exists -- by an EXACT key match, never
// by "the search returned something".
//
// `GET /tasks?s=` is a SUBSTRING search. The pull-request path's sibling node
// takes `searchResults[0].id`, which is safe there only because it is looking
// for a task it expects to find. Reused here it would be a silent bug: searching
// `TOOL-035` also matches a task titled `TOOL-0350: ...`, so the create path
// would conclude TOOL-035 already exists and never create it -- and answer 200.
const event = $('Parse Forge Event').first().json;

// READ THE ITEMS, NOT `$json`. n8n passes data between nodes as an ARRAY OF
// ITEMS, and an HTTP node handed a JSON array emits ONE ITEM PER ELEMENT -- so
// `$json` here is the FIRST task, not the list. `Array.isArray($json)` would be
// false, `$json.data` undefined, and the node would conclude "no results" while
// looking straight at them: it would create a duplicate of a task it can see.
//
// `$input.all()` is shape-agnostic and covers every form the request can take:
// N split items, one item wrapping an array, one wrapping `{data: [...]}`, the
// empty item `alwaysOutputData` emits, and the error item `continueOnFail` emits.
const items = $input.all().map(i => i.json);

// A search that ERRORED is not a search that found nothing. `continueOnFail` on
// the request node turns a 401/timeout into an item carrying `error`, which is
// indistinguishable from an empty result set unless it is checked. Creating on
// that would duplicate a task that already exists.
const searchFailed = items.some(i => i && i.error);

let results;
if (items.length === 1 && Array.isArray(items[0])) {
  results = items[0];
} else if (items.length === 1 && items[0] && Array.isArray(items[0].data)) {
  results = items[0].data;
} else {
  // The split-items shape. The empty item `alwaysOutputData` emits (`{}`) and
  // the error item both lack `id`, so both correctly reduce to no results.
  results = items.filter(i => i && i.id);
}

const key = (event.taskKey || '').toUpperCase();
const exact = results.filter(t => {
  const title = (t.title || '').toUpperCase();
  if (!key || !title.startsWith(key)) return false;
  // Reject only a continuing DIGIT: `TOOL-035` must not match `TOOL-0350`, but
  // must match both `TOOL-035: slug` and `TOOL-035-slug`, since the board's ID
  // convention is `AREA-NNN-slug` and the issue title renders it `AREA-NNN: ...`.
  return !/[0-9]/.test(title.charAt(key.length));
});

// AC1 by construction, not by convention. The key is extracted from anywhere in
// the title, so an issue called `fix the TOOL-035 thing` would otherwise produce
// a task whose title does not START with the key -- and `?s=` would still find
// it, right up until a second AREA collides. Prefixing when it is absent makes
// the join key a property of every task this path creates.
const rawTitle = (event.title || '').trim();
const taskTitle = rawTitle.toUpperCase().startsWith(key) ? rawTitle : (event.taskKey + ': ' + rawTitle);

return [{
  json: {
    ...event,
    searchFailed: searchFailed,
    existingTaskId: exact.length > 0 ? exact[0].id : null,
    taskAlreadyExists: exact.length > 0,
    notCreatedReason: exact.length > 0 ? 'task already exists in vikunja' : null,
    taskTitle: taskTitle,
    taskDescription: '<p>Forge issue: <a href="' + event.issueUrl + '">'
      + event.repoOwner + '/' + event.repoName + '#' + event.issueNumber + '</a></p>'
  }
}];

// Resolve which Vikunja project the new task belongs to.
//
// ONE BOARD, not one per organisation. ADR-066 originally mirrored ADR-065's
// Gitea orgs into three Vikunja namespaces; that is withdrawn (see the reasoning
// on `apps.services.core.vikunja.default_project` in common.yaml). Provenance
// lives in the `AREA-NNN` key that every task title must carry and in `area:*`
// labels -- splitting by project duplicated information already travelling in
// the field the whole integration joins on, and cost the single "what is next"
// board that Kanban buckets cannot span.
//
// The title comes from SSOT, substituted at import time by `n8n_import`, the
// same convention `cluster_bootstrap` uses for the RPi4 MagicDNS token (that
// token is deliberately NOT spelled out here: the scanner cannot tell a
// documentation mention from a real use, and would demand a mapping for it).
// It is NOT read
// from `$env`: `n8n-config` is a plain ConfigMap rather than a
// `configMapGenerator` entry, so a changed key would leave the pod on the old
// value while Argo CD reported Synced (lesson-404).
//
// Matched by TITLE and not by id. An id is environment-specific and opaque, so
// the same workflow would silently target a different board per environment.
const DECLARED_PROJECT = 'RESOLVE_VIKUNJA_DEFAULT_PROJECT';

const event = $('Extract Issue Task Match').first().json;

// `$input.all()`, not `$json` -- `GET /projects` returns a JSON array and n8n
// emits one item per element, so `$json` is the FIRST project. Reading it as the
// list would find no match and answer 422 forever.
const items = $input.all().map(i => i.json);

let projects;
if (items.length === 1 && Array.isArray(items[0])) {
  projects = items[0];
} else if (items.length === 1 && items[0] && Array.isArray(items[0].data)) {
  projects = items[0].data;
} else {
  projects = items.filter(i => i && i.id);
}

const projectLookupFailed = items.some(i => i && i.error);
const norm = s => (s || '').toString().trim().toLowerCase();

const picked = projects.find(p => norm(p.title) === norm(DECLARED_PROJECT)) || null;

// Still fails closed, and the reason is unchanged even though the cause moved:
// nothing watches a webhook, so filing into whatever project happens to be first
// would be invisible and permanent. `slack-task-capture` can default to project 1
// because a human typed the command and sees where it landed.
return [{
  json: {
    ...event,
    projectId: picked ? picked.id : null,
    projectTitle: picked ? picked.title : null,
    declaredProject: DECLARED_PROJECT,
    projectLookupFailed: projectLookupFailed,
    readyToCreate: Boolean(picked && picked.id && !event.searchFailed && !projectLookupFailed)
  }
}];
